@OptIn(ExperimentalMaterial3ExpressiveApi::class)
@Composable
fun ShapeIcon(icon: ImageVector, shape: RoundedPolygon, container: Color, content: Color, size: Dp = 40.dp) {
    Box(Modifier.size(size).clip(shape.toShape()).background(container), contentAlignment = Alignment.Center) {
        Icon(icon, contentDescription = null, tint = content, modifier = Modifier.size(size * 0.55f))
    }
}
